import {
  Component, Input, Output, EventEmitter, OnInit, OnChanges, SimpleChanges,
  ViewChild, ChangeDetectionStrategy, ChangeDetectorRef, effect
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { TranscriptToolbarComponent, ToolbarEvent } from './transcript-toolbar/transcript-toolbar.component';
import { TranscriptContentComponent } from './transcript-content/transcript-content.component';
import { VersionSelectorComponent } from './version-selector/version-selector.component';
import { TranscriptService } from '../../../adminpanel/services/transcript/transcript.service';
import { TranscriptVersion } from '../../../adminpanel/interfaces/transcript-version.interface';
import { TranscriptRendererService } from '../../services/transcript-renderer/transcript-renderer.service';
import { RealtimeService } from '../../services/realtime/realtime.service';
import { FeedUtilityService } from '../../services/feed-utility/feed-utility.service';
import { ToolbarComponent } from '../feeds/rt-components/toolbar/toolbar.component';
import { FeedDisplayService } from '../../services/feed-display/feed-display.service';
import { AnnotsService } from '../../services/annots/annots.service';
import { SearchService } from '../../search/search.service';
import { FeedIndexService } from '../../services/index/feed-index/feed-index.service';
import { annotTrasnferService } from '../../services/feed-display/annot.transfer.service';
import { SideModalManagerComponent } from '../side-modal-manager/side-modal-manager.component';
import { feeds, finalFeedData, feedPage, PageParsedItem, sessionDetail } from '@rt/interfaces';
import { hightlightModeType } from '../../interfaces/feed.interface';
import { environment } from '../../../../environments/environment';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { SelectionActionsService } from '../../../shared/services/selection-actions/selection-actions.service';

@Component({
  selector: 'transcript-viewer',
  standalone: true,
  imports: [
    CommonModule,
    TranslateModule,
    TranscriptToolbarComponent,
    TranscriptContentComponent,
    VersionSelectorComponent,
    ToolbarComponent,
    SideModalManagerComponent,
  ],
  providers: [FeedDisplayService, AnnotsService, annotTrasnferService, SearchService, FeedIndexService],
  templateUrl: './transcript-viewer.component.html',
  styleUrls: ['./transcript-viewer.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TranscriptViewerComponent implements OnInit, OnChanges {
  @Input() nSesid: string;
  @Input() viewMode: 'sidebar' | 'full' | 'evidence' = 'full';
  @Input() nCaseid: string;
  @Input() nUserid: string;
  @Input() preloadedHtml: string;
  @Input() feedData: feeds[];
  /** Hide MarkNav / Compare / Kebab menu in the rt-toolbar — used for
   *  the transcript folder preview panel. */
  @Input() hideSecondaryActions: boolean = false;
  /** Emits toolbar events (e.g. COMPARE_MODE) to the parent component. */
  @Output() toolBarEvents = new EventEmitter<any>();

  @ViewChild('contentRef') contentRef: TranscriptContentComponent;

  htmlContent: string = '';
  loading: boolean = false;
  /** Set to true once a load attempt finishes without producing any content — drives the empty-state UI. */
  hasNoContent: boolean = false;
  sessionDetail: sessionDetail | null = null;
  currentPage: number = 1;
  totalPages: number = 1;
  showTimestamps: boolean = true;
  showLineNumbers: boolean = true;
  zoomLevel: number = 100;
  /** RT toolbar uses decimal zoom (1 = 100%, 1.2 = fit-height) */
  zoomLevelRt: number = 1;
  searchTerm: string = '';
  currentVersion: TranscriptVersion | null = null;
  hasVersions: boolean = false;
  visibleMarkNavModel: boolean = false;
  visibleIssueModel: boolean = false;
  /** One-shot flag set when the user clicks the QFact panel's Manage button.
   *  Side-modal-manager passes this to issue-manage so QFact mode auto-toggles
   *  on. Cleared when the issue-manage panel closes. */
  qfactManagePending: boolean = false;
  /** Drives the qFact / Fact / DocLink panel rendering inside side-modal-manager.
   *  Synced from SelectionActionsService.singleKind() so the panel opens when the
   *  toolbar pill is set to a single mode (QFact / Fact / DocLink). */
  hightlightMode: hightlightModeType = null;

  constructor(
    private transcriptService: TranscriptService,
    private rendererService: TranscriptRendererService,
    private realtimeService: RealtimeService,
    private feedUtility: FeedUtilityService,
    private secureStorage: SecureStorageService,
    private tost: TostbarService,
    private cdr: ChangeDetectorRef,
    private selectionActions: SelectionActionsService,
  ) {
    effect(() => {
      const single = this.selectionActions.singleKind();
      this.hightlightMode = single ?? null;
      this.cdr.markForCheck();
    });

    // Manage button on the QFact panel / tab: open the existing
    // `issue-manage` side panel with QFact mode pre-enabled, instead of
    // the old standalone ManageIssuesDialogComponent popup. The
    // subscription is auto-cleaned when this OnPush component is
    // destroyed because effect() / RxJS subjects don't outlive the
    // service injector — the service is provided in root, so we attach
    // a manual unsubscribe in ngOnDestroy below.
    this._qfactManageSub = this.selectionActions.qfactManageRequest$.subscribe(() => {
      if (!this.nCaseid || !this.nUserid) return;
      this.qfactManagePending = true;
      this.visibleIssueModel = true;
      this.cdr.markForCheck();
    });
  }

  private _qfactManageSub: any;

  /** Reset the pending flag when the panel closes so future re-opens
   *  (from a different entry point) don't auto-enable QFact mode. */
  onVisibleIssueModelChange(v: boolean): void {
    this.visibleIssueModel = v;
    if (!v) this.qfactManagePending = false;
  }

  async ngOnInit(): Promise<void> {
    if (!this.nUserid) {
      this.nUserid = await this.secureStorage.getUserId();
    }
    await this.loadContent();
  }

  async ngOnChanges(changes: SimpleChanges): Promise<void> {
    if (changes['nSesid'] && !changes['nSesid'].firstChange) {
      await this.loadContent();
    }
    if (changes['preloadedHtml'] && this.preloadedHtml) {
      this.htmlContent = this.preloadedHtml;
      this.countPages();
      this.cdr.markForCheck();
    }
    if (changes['feedData'] && this.feedData) {
      this.renderFromFeedData(this.feedData);
    }
  }

  /**
   * Main content loading logic:
   * 1. If preloadedHtml is provided, use it directly
   * 2. If feedData is provided, render from structured data
   * 3. Try to fetch a persisted version from the versioning API
   * 4. Fallback: fetch feed data from realtime API (same as RT module) and render
   */
  private async loadContent(): Promise<void> {
    if (this.preloadedHtml) {
      this.htmlContent = this.preloadedHtml;
      this.countPages();
      return;
    }

    if (this.feedData?.length) {
      this.renderFromFeedData(this.feedData);
      return;
    }

    if (!this.nSesid) return;

    if (!this.nUserid) {
      this.nUserid = await this.secureStorage.getUserId();
    }

    this.loading = true;
    this.hasNoContent = false;
    this.cdr.markForCheck();

    // Fetch session detail immediately so toolbar can render
    try {
      this.sessionDetail = await this.realtimeService.getSessionDetail(this.nSesid, this.nUserid);
      this.cdr.markForCheck();
    } catch (e) {
      console.warn('Could not load session detail for toolbar');
    }

    try {
      // Step 1: Try to load a persisted version (may fail if backend not set up yet)
      try {
        const versionRes = await this.transcriptService.getLatestVersion(this.nSesid);
        if (versionRes?.msg === 1 && versionRes.data?.html_content) {
          this.currentVersion = versionRes.data;
          this.htmlContent = versionRes.data.html_content;
          this.hasVersions = true;
          this.loading = false;
          this.countPages();
          this.cdr.markForCheck();
          return;
        }
      } catch (versionErr) {
        // Version API not available yet — continue to fallback
        console.log('Version API not available, falling back to realtime API');
      }

      // Step 2: Fallback — fetch feed data from realtime API (same endpoint as RT module)
      await this.loadFromRealtimeApi();

    } catch (err) {
      console.error('Failed to load transcript content:', err);
    } finally {
      this.loading = false;
      this.countPages();
      this.cdr.markForCheck();
    }
  }

  /**
   * Loads transcript data from the realtime API — same data source the RT feed uses.
   * Endpoint: GET /session/realtimedatabysesid
   */
  private async loadFromRealtimeApi(): Promise<void> {
    if (!this.nUserid) {
      this.nUserid = await this.secureStorage.getUserId();
    }
    console.log('[TranscriptViewer] loadFromRealtimeApi — nSesid:', this.nSesid, 'nUserid:', this.nUserid, 'nCaseid:', this.nCaseid);

    // Get session detail first to know case ID and session metadata
    const detail = await this.realtimeService.getSessionDetail(this.nSesid, this.nUserid);
    console.log('[TranscriptViewer] sessionDetail:', detail);
    this.sessionDetail = detail;
    if (!detail) {
      console.warn('[TranscriptViewer] Session detail not found for', this.nSesid);
      return;
    }

    const caseid = this.nCaseid || detail.nCaseid;
    const isTrans = detail.isTrans;
    console.log('[TranscriptViewer] caseid:', caseid, 'isTrans:', isTrans);

    // Fetch feed data. The backend wraps the pages array in { msg, data } for published
    // sessions (msg=1) but returns a raw array for live/draft sessions. Unwrap defensively
    // so both shapes render — without this, the published branch fails the Array.isArray
    // check below and falls through to the "No feed data" empty state.
    const feedResRaw = await this.realtimeService.getRealtimeDataBySessionId(
      this.nSesid, this.nUserid, caseid
    );
    const feedRes: any[] = Array.isArray(feedResRaw)
      ? feedResRaw
      : (feedResRaw?.msg === 1 && Array.isArray(feedResRaw.data) ? feedResRaw.data : []);
    console.log('[TranscriptViewer] feedRes:', feedRes?.length, 'pages', feedRes?.[0] ? 'first page data count:' + feedRes[0]?.data?.length : 'no data');

    if (feedRes && feedRes.length) {
      const pages: feeds[] = feedRes.map((page: any) => {
        let parsedData: finalFeedData[];

        // Detect shape from the data itself rather than trusting detail.isTrans.
        // The SP still returns isTrans=false for published sessions, so a flag-based
        // fork would mis-route published data into the raw-tuple parsing path.
        // Pre-parsed objects: [{ lines, time, oPage, oLine, ... }]
        // Raw tuples:         [[...], [...], ...]
        if (page.data?.length && typeof page.data[0] === 'object' && !Array.isArray(page.data[0])) {
          parsedData = page.data as finalFeedData[];
        } else if (page.data?.length && Array.isArray(page.data[0])) {
          parsedData = this.feedUtility.parseFeedLineData(page.data as PageParsedItem[]);
        } else {
          parsedData = page.data as finalFeedData[] || [];
        }

        return { page: page.page, data: parsedData, msg: page.page };
      });
      console.log('[TranscriptViewer] Rendering', pages.length, 'pages');
      this.renderFromFeedData(pages);
    } else if (detail.pageRes) {
      // Use initial page data from session detail
      console.log('[TranscriptViewer] Using pageRes fallback');
      const pageRes = detail.pageRes;
      if (pageRes.data?.length) {
        let data = pageRes.data;
        if (Array.isArray(data[0])) {
          data = this.feedUtility.parseFeedLineData(data as any as PageParsedItem[]);
        }
        this.renderFromFeedData([{ page: pageRes.page, data: data as finalFeedData[], msg: pageRes.msg }]);
      }
    } else {
      console.warn('[TranscriptViewer] No feed data found for session', this.nSesid);
      this.hasNoContent = true;
      this.cdr.markForCheck();
    }
  }

  /**
   * Render HTML from structured feed data using TranscriptRendererService
   */
  private renderFromFeedData(data: feeds[]): void {
    if (!data?.length) return;

    this.htmlContent = this.rendererService.renderToHtml(data, {
      includeTimestamps: this.showTimestamps,
      includeLineNumbers: this.showLineNumbers,
      includePageBreaks: this.viewMode === 'full',
      cssMode: 'linked',
    });
    this.hasNoContent = false;
    this.countPages();
    this.cdr.markForCheck();
  }

  private countPages(): void {
    if (!this.htmlContent) {
      this.totalPages = 0;
      return;
    }
    const matches = this.htmlContent.match(/class="transcript-page/g);
    this.totalPages = matches ? matches.length : 1;
  }

  onToolbarAction(event: ToolbarEvent): void {
    switch (event.action) {
      case 'search':
        this.searchTerm = event.data || '';
        break;
      case 'jump-to-page':
        this.contentRef?.scrollToPage(event.data);
        break;
      case 'toggle-timestamps':
        this.showTimestamps = !this.showTimestamps;
        break;
      case 'toggle-line-numbers':
        this.showLineNumbers = !this.showLineNumbers;
        break;
      case 'zoom-in':
        this.zoomLevel = Math.min(this.zoomLevel + 10, 200);
        break;
      case 'zoom-out':
        this.zoomLevel = Math.max(this.zoomLevel - 10, 50);
        break;
      case 'zoom-reset':
        this.zoomLevel = 100;
        break;
      case 'export-pdf':
        this.handleExportPdf();
        break;
      case 'export-docx':
        this.handleExportDocx();
        break;
      case 'copy':
        this.handleCopy();
        break;
    }
    this.cdr.markForCheck();
  }

  /** Handle session switch from RT toolbar */
  async onSessionSwitch(nSesid: string): Promise<void> {
    this.nSesid = nSesid;
    await this.loadContent();
  }

  /** Handle page change from RT toolbar "Go to Page" */
  onPageChange(page: number): void {
    this.currentPage = page;
    this.contentRef?.scrollToPage(page);
    this.cdr.markForCheck();
  }

  /** Handle timestamp toggle from RT toolbar three-dot menu */
  onTimestampToggle(show: boolean): void {
    this.showTimestamps = show;
    this.cdr.markForCheck();
  }

  /** Handle zoom change from RT toolbar three-dot menu */
  onZoomChange(level: number): void {
    this.zoomLevelRt = level;
    // Convert RT decimal zoom (1 = 100%) to percentage for content
    this.zoomLevel = Math.round(level * 100);
    this.cdr.markForCheck();
  }

  /** Handle RT toolbar events (export, toggle-demo, etc.) */
  onRtToolbarEvent(event: any): void {
    if (!event?.type) return;
    switch (event.type) {
      case 'EXPORT-TRANSCRIPT':
        this.handleExportDocx();
        break;
      case 'TOGGLE-DEMO':
        // Demo playback not applicable in individual doc
        break;
      case 'COMPARE_MODE':
        // Propagate to parent (individual-doc) to activate compare mode
        console.log('[COMPARE] transcript-viewer: propagating COMPARE_MODE to parent');
        this.toolBarEvents.emit(event);
        break;
    }
  }

  onVersionSelected(version: TranscriptVersion): void {
    this.currentVersion = version;
    if (version.html_content) {
      this.htmlContent = version.html_content;
      this.countPages();
      this.cdr.markForCheck();
    }
  }

  async onReopenRequested(nVersionid: string): Promise<void> {
    const res = await this.transcriptService.reopenVersion({ nVersionid });
    if (res.msg === 1 && res.data?.html_content) {
      this.currentVersion = res.data;
      this.htmlContent = res.data.html_content;
      this.countPages();
      this.cdr.markForCheck();
    }
  }

  private async handleExportPdf(): Promise<void> {
    if (!this.currentVersion?.nVersionid && !this.htmlContent) {
      this.tost.openSnackBar('No content to export', 'E');
      return;
    }
    if (this.currentVersion?.nVersionid) {
      const res = await this.transcriptService.exportPdf(this.currentVersion.nVersionid);
      if (res.msg === 1 && res.path) {
        this.downloadFile(res.path);
      }
    }
  }

  private async handleExportDocx(): Promise<void> {
    if (!this.nSesid) return;
    const res = await this.transcriptService.downloadDoc('', this.nSesid);
    if (res && res.msg !== -1) {
      this.tost.openSnackBar('Document export started', '');
    }
  }

  private handleCopy(): void {
    const selection = window.getSelection();
    if (selection && selection.toString()) {
      navigator.clipboard.writeText(selection.toString()).then(() => {
        this.tost.openSnackBar('Copied to clipboard', '');
      });
    }
  }

  private downloadFile(path: string): void {
    const url = `${environment.cloudUrl2}${environment.realtimeserive}/realtime-transcripts/exports/${path}`;
    const a = document.createElement('a');
    a.href = url;
    a.download = path.split('/').pop() || 'transcript.pdf';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  ngOnDestroy(): void {
    this._qfactManageSub?.unsubscribe?.();
  }
}
