import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { TranscriptService } from '../../../../adminpanel/services/transcript/transcript.service';
import { TranscriptVersion } from '../../../../adminpanel/interfaces/transcript-version.interface';
import { ButtonComponent } from '../../../../shared/components/button/button.component';

@Component({
  selector: 'version-selector',
  standalone: true,
  imports: [CommonModule, FormsModule, TranslateModule, ButtonComponent],
  template: `
    <div class="flex items-center gap-2">
      <select
        [(ngModel)]="selectedVersionId"
        (ngModelChange)="onVersionChange($event)"
        class="px-2 py-1 border border-neutral-300 rounded text-sm focus:outline-none focus:border-blue-500 bg-white">
        @for (version of versions; track version.nVersionid) {
          <option [value]="version.nVersionid">
            v{{ version.nVersion }}
            {{ version.is_published ? '(Published)' : '(Draft)' }}
            - {{ version.dCreatedt | date:'short' }}
          </option>
        }
      </select>

      @if (canReopen) {
        <button
          class="text-xs px-2 py-1 border border-neutral-300 rounded hover:bg-neutral-50 text-neutral-600"
          (click)="onReopen()"
          title="Create new draft from this published version">
          {{ 'transcript.reopenAsDraft' | translate }}
        </button>
      }
    </div>
  `,
})
export class VersionSelectorComponent implements OnInit {
  @Input() nSesid: string;
  @Output() versionSelected = new EventEmitter<TranscriptVersion>();
  @Output() reopenRequested = new EventEmitter<string>();

  versions: TranscriptVersion[] = [];
  selectedVersionId: string = '';

  get canReopen(): boolean {
    const selected = this.versions.find(v => v.nVersionid === this.selectedVersionId);
    return selected?.is_published === true;
  }

  constructor(private transcriptService: TranscriptService) {}

  async ngOnInit(): Promise<void> {
    await this.loadVersions();
  }

  async loadVersions(): Promise<void> {
    if (!this.nSesid) return;
    const res = await this.transcriptService.getVersionList(this.nSesid);
    if (res.msg === 1 && res.data?.length) {
      this.versions = res.data;
      // Select latest version by default
      this.selectedVersionId = this.versions[0].nVersionid;
    }
  }

  async onVersionChange(nVersionid: string): Promise<void> {
    const res = await this.transcriptService.getVersion(nVersionid);
    if (res.msg === 1 && res.data) {
      this.versionSelected.emit(res.data);
    }
  }

  onReopen(): void {
    this.reopenRequested.emit(this.selectedVersionId);
  }
}
