import { Component, EventEmitter, Input, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { TranslateModule } from '@ngx-translate/core';

export interface ToolbarConfig {
  showSearch: boolean;
  showJumpToPage: boolean;
  showHighlight: boolean;
  showCopy: boolean;
  showExport: boolean;
  showAnnotations: boolean;
  showZoom: boolean;
  showFilter: boolean;
  showVersionSelector: boolean;
  showTimestampToggle: boolean;
}

export const TOOLBAR_CONFIGS: Record<string, ToolbarConfig> = {
  sidebar: {
    showSearch: true,
    showJumpToPage: true,
    showHighlight: true,
    showCopy: true,
    showExport: false,
    showAnnotations: false,
    showZoom: false,
    showFilter: false,
    showVersionSelector: false,
    showTimestampToggle: true,
  },
  full: {
    showSearch: true,
    showJumpToPage: true,
    showHighlight: true,
    showCopy: true,
    showExport: true,
    showAnnotations: true,
    showZoom: true,
    showFilter: true,
    showVersionSelector: true,
    showTimestampToggle: true,
  },
  evidence: {
    showSearch: true,
    showJumpToPage: false,
    showHighlight: true,
    showCopy: true,
    showExport: false,
    showAnnotations: false,
    showZoom: false,
    showFilter: false,
    showVersionSelector: false,
    showTimestampToggle: false,
  }
};

export type ToolbarAction =
  | 'search'
  | 'jump-to-page'
  | 'highlight'
  | 'copy'
  | 'export'
  | 'export-pdf'
  | 'export-docx'
  | 'annotations'
  | 'zoom-in'
  | 'zoom-out'
  | 'zoom-reset'
  | 'filter'
  | 'toggle-timestamps'
  | 'toggle-line-numbers'
  | 'version-select';

export interface ToolbarEvent {
  action: ToolbarAction;
  data?: any;
}

@Component({
  selector: 'transcript-toolbar',
  standalone: true,
  imports: [CommonModule, FormsModule, IconComponent, ButtonComponent, TranslateModule],
  templateUrl: './transcript-toolbar.component.html',
})
export class TranscriptToolbarComponent {
  @Input() mode: 'sidebar' | 'full' | 'evidence' = 'full';
  @Input() currentPage: number = 1;
  @Input() totalPages: number = 1;
  @Input() showTimestamps: boolean = true;
  @Input() showLineNumbers: boolean = true;
  @Input() zoomLevel: number = 100;

  @Output() toolbarAction = new EventEmitter<ToolbarEvent>();

  searchTerm: string = '';
  searchOpen: boolean = false;
  jumpPage: number = 1;

  get config(): ToolbarConfig {
    return TOOLBAR_CONFIGS[this.mode] || TOOLBAR_CONFIGS['full'];
  }

  onSearch(): void {
    this.toolbarAction.emit({ action: 'search', data: this.searchTerm });
  }

  onJumpToPage(): void {
    if (this.jumpPage >= 1 && this.jumpPage <= this.totalPages) {
      this.toolbarAction.emit({ action: 'jump-to-page', data: this.jumpPage });
    }
  }

  onToggleTimestamps(): void {
    this.toolbarAction.emit({ action: 'toggle-timestamps' });
  }

  onToggleLineNumbers(): void {
    this.toolbarAction.emit({ action: 'toggle-line-numbers' });
  }

  onExportPdf(): void {
    this.toolbarAction.emit({ action: 'export-pdf' });
  }

  onExportDocx(): void {
    this.toolbarAction.emit({ action: 'export-docx' });
  }

  onZoomIn(): void {
    this.toolbarAction.emit({ action: 'zoom-in' });
  }

  onZoomOut(): void {
    this.toolbarAction.emit({ action: 'zoom-out' });
  }

  jumpToFirstPage(): void {
    this.toolbarAction.emit({ action: 'jump-to-page', data: 1 });
  }

  jumpToLastPage(): void {
    this.toolbarAction.emit({ action: 'jump-to-page', data: this.totalPages });
  }

  prevPage(): void {
    if (this.currentPage > 1) {
      this.toolbarAction.emit({ action: 'jump-to-page', data: this.currentPage - 1 });
    }
  }

  nextPage(): void {
    if (this.currentPage < this.totalPages) {
      this.toolbarAction.emit({ action: 'jump-to-page', data: this.currentPage + 1 });
    }
  }

  onPageInputChange(event: Event): void {
    const input = event.target as HTMLInputElement;
    const page = parseInt(input.value, 10);
    if (page >= 1 && page <= this.totalPages) {
      this.toolbarAction.emit({ action: 'jump-to-page', data: page });
    }
  }

  onZoomReset(): void {
    this.toolbarAction.emit({ action: 'zoom-reset' });
  }

  onHighlight(): void {
    this.toolbarAction.emit({ action: 'highlight' });
  }

  onCopy(): void {
    this.toolbarAction.emit({ action: 'copy' });
  }

  onFilter(): void {
    this.toolbarAction.emit({ action: 'filter' });
  }

  onAnnotations(): void {
    this.toolbarAction.emit({ action: 'annotations' });
  }

  toggleSearch(): void {
    this.searchOpen = !this.searchOpen;
    if (!this.searchOpen) {
      this.searchTerm = '';
      this.onSearch();
    }
  }
}
