import {
  Component, Input, Output, EventEmitter, OnChanges, SimpleChanges,
  ViewChild, ElementRef, ChangeDetectionStrategy, ChangeDetectorRef
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { ScrollingModule, CdkVirtualScrollViewport } from '@angular/cdk/scrolling';
import { TranslateModule } from '@ngx-translate/core';
import { EmptyComponent } from '../../../../shared/components/empty/empty.component';

export interface TranscriptPage {
  pageNumber: number;
  html: string;
  safeHtml: SafeHtml;
}

@Component({
  selector: 'transcript-content',
  standalone: true,
  imports: [CommonModule, ScrollingModule, TranslateModule, EmptyComponent],
  templateUrl: './transcript-content.component.html',
  styleUrls: ['./transcript-content.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TranscriptContentComponent implements OnChanges {
  @Input() htmlContent: string = '';
  @Input() mode: 'sidebar' | 'full' | 'evidence' = 'full';
  @Input() zoomLevel: number = 100;
  @Input() showTimestamps: boolean = true;
  @Input() showLineNumbers: boolean = true;
  @Input() searchTerm: string = '';
  @Input() loading: boolean = false;

  @Output() pageChange = new EventEmitter<number>();
  @Output() lineClick = new EventEmitter<{ page: number; line: number; identity?: string }>();

  @ViewChild('virtualScroll') virtualScroll: CdkVirtualScrollViewport;
  @ViewChild('scrollContainer') scrollContainer: ElementRef<HTMLDivElement>;

  htmlPages: TranscriptPage[] = [];
  estimatedPageHeight = 800;
  baseFontSize = 15;

  constructor(
    private sanitizer: DomSanitizer,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['htmlContent'] && this.htmlContent) {
      this.parseHtmlIntoPages();
    }
    if (changes['showTimestamps'] || changes['showLineNumbers']) {
      this.applyVisibilityToggles();
    }
    if (changes['searchTerm']) {
      this.applySearchHighlight();
    }
  }

  /**
   * Parses the canonical HTML document string into individual page chunks
   * for virtual scrolling.
   */
  private parseHtmlIntoPages(): void {
    if (!this.htmlContent) {
      this.htmlPages = [];
      return;
    }

    // Parse the HTML to extract individual page divs
    const parser = new DOMParser();
    const doc = parser.parseFromString(this.htmlContent, 'text/html');
    const pageElements = doc.querySelectorAll('.transcript-page');

    if (pageElements.length === 0) {
      // No page structure found — treat entire content as single page
      this.htmlPages = [{
        pageNumber: 1,
        html: this.htmlContent,
        safeHtml: this.sanitizer.bypassSecurityTrustHtml(this.htmlContent)
      }];
    } else {
      this.htmlPages = Array.from(pageElements).map((el, index) => {
        const pageNum = parseInt(el.getAttribute('data-page') || `${index + 1}`, 10);
        const html = el.outerHTML;
        return {
          pageNumber: pageNum,
          html,
          safeHtml: this.sanitizer.bypassSecurityTrustHtml(html)
        };
      });
    }

    // Estimate page height based on mode
    this.estimatedPageHeight = this.mode === 'sidebar' ? 400 : 800;
    this.cdr.markForCheck();
  }

  /**
   * Scrolls to a specific page number
   */
  scrollToPage(pageNumber: number): void {
    const index = this.htmlPages.findIndex(p => p.pageNumber === pageNumber);
    if (index >= 0 && this.virtualScroll) {
      this.virtualScroll.scrollToIndex(index, 'smooth');
    }
  }

  /**
   * Scrolls to a specific line within a page
   */
  scrollToLine(pageNumber: number, lineNumber: number): void {
    this.scrollToPage(pageNumber);
    // After scroll, find and scroll to the specific line element
    setTimeout(() => {
      const lineEl = this.scrollContainer?.nativeElement?.querySelector(
        `[data-page="${pageNumber}"][data-line="${lineNumber}"]`
      );
      if (lineEl) {
        lineEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        // Add temporary highlight
        lineEl.classList.add('search-highlight-current');
        setTimeout(() => lineEl.classList.remove('search-highlight-current'), 2000);
      }
    }, 300);
  }

  /**
   * Apply visibility toggles for timestamps and line numbers
   */
  private applyVisibilityToggles(): void {
    // Re-parse pages with updated visibility CSS
    // This is handled via CSS classes rather than DOM manipulation
    this.cdr.markForCheck();
  }

  /**
   * Apply search term highlighting to the rendered HTML
   */
  private applySearchHighlight(): void {
    if (!this.searchTerm || !this.htmlPages.length) {
      // Reset to original HTML
      this.htmlPages = this.htmlPages.map(p => ({
        ...p,
        safeHtml: this.sanitizer.bypassSecurityTrustHtml(p.html)
      }));
      this.cdr.markForCheck();
      return;
    }

    const escapedTerm = this.searchTerm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`(${escapedTerm})`, 'gi');

    this.htmlPages = this.htmlPages.map(p => {
      // Only highlight within .line-text spans to avoid breaking HTML structure
      const highlighted = p.html.replace(
        /(<span class="line-text">)([\s\S]*?)(<\/span>)/g,
        (match, open, content, close) => {
          return open + content.replace(regex, '<mark class="search-highlight">$1</mark>') + close;
        }
      );
      return {
        ...p,
        safeHtml: this.sanitizer.bypassSecurityTrustHtml(highlighted)
      };
    });
    this.cdr.markForCheck();
  }

  trackByPage(index: number, page: TranscriptPage): number {
    return page.pageNumber;
  }
}
